mapper.select:
select a.task_id, b.device_id, b.instance_id, e.real_code, d.device_name, f.instance_name, g.point_type, h.dict_note as cruise_type, g.result_num, g.state, j.dict_note as data_state, b.cruise_time, g.identify_state, k.dict_note as identify_state1 from t_cruise_result a, t_cruise_task_result_detail b, t_std_device d, t_std_device_attr e, t_cruise_point_attr f, t_cruise_data_result g, t_dict_business h, t_dict_business j, t_dict_business k where a.task_id = #{taskId} and a.task_result_id = b.task_result_id and d.device_id = b.device_id and e.device_id = b.device_id and b.instance_id = f.instance_id and g.cruise_result_id = b.cruise_result_id and h.dict_code = g.point_type and j.dict_code = g.state and k.dict_code = g.identify_state and d.device_name like concat ('%',#{deviceName,jdbcType=VARCHAR},'%') and d.device_id like concat ('%',#{deviceId,jdbcType=INTEGER},'%')
and g.point_type = #{pointType, jdbcType=INTEGER} and h.dict_note = #{cruiseType, jdbcType=VARCHAR}
and g.state = #{state, jdbcType=INTEGER} and j.dict_note = #{dataState, jdbcType=VARCHAR}
